/* Scoped by the static .three-ripple class (set on the root by Hooks).
   Per-instance {{id}} interpolation is unreliable in preview/publish builds,
   so no template interpolation is used in this file. */

.three-ripple {
  position: relative;
  display: block;
  box-sizing: border-box;
  flex: 1 1 auto;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 16rem;
  overflow: hidden;
  isolation: isolate;
  background: var(--color-neutral-950);
}

.three-ripple .three-ripple__source,
.three-ripple .three-ripple__canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.three-ripple .three-ripple__source {
  z-index: 1;
}

.three-ripple .three-ripple__source img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.three-ripple .three-ripple__canvas {
  z-index: 2;
  display: block;
  opacity: 0;
  pointer-events: none;
  transition: opacity 240ms ease;
}

.three-ripple .three-ripple__canvas canvas {
  display: block;
  width: 100%;
  height: 100%;
}

.three-ripple.is-ready .three-ripple__canvas {
  opacity: 1;
}

.three-ripple.is-ready .three-ripple__source {
  visibility: hidden;
}

@media (prefers-reduced-motion: reduce) {
  .three-ripple .three-ripple__canvas {
    transition: none;
  }
}

