import * as THREE from 'three';

const attrSrc = (image) => (image && image.getAttribute('src')) || '';

const liveImage = (canvas) => {
  const root = canvas.closest('.three-ripple');
  if (root) {
    const image = root.querySelector('.three-ripple__source img');
    if (image) return image;
  }
  const host = canvas.parentElement;
  return host?.parentElement?.querySelector('.three-ripple__source img') || null;
};

const loadUrl = (url) => new Promise((resolve) => {
  if (!url) {
    resolve(null);
    return;
  }
  const image = new Image();
  image.onload = () => resolve(image.naturalWidth > 0 ? image : null);
  image.onerror = () => resolve(null);
  image.src = url;
});

export function mount(el, props) {
  const canvas = document.createElement('canvas');
  canvas.setAttribute('aria-hidden', 'true');
  el.appendChild(canvas);

  const getRoot = () => {
    if (canvas.isConnected) {
      const live = canvas.closest('.three-ripple');
      if (live) return live;
    }
    return el.closest('.three-ripple') || el.parentElement;
  };

  let renderer = null;
  let scene = null;
  let camera = null;
  let geometry = null;
  let material = null;
  let texture = null;
  let uniforms = null;
  let frame = 0;
  let last = performance.now();
  let targetActivity = 0;
  let destroyed = false;
  let visible = true;
  let pending = props || {};
  let lastLoadedSrc = '';
  let loadGen = 0;
  let resizeObserver = null;
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');

  const applyProps = (next) => {
    pending = next || {};
    if (!uniforms) return;
    uniforms.uStrength.value = Number(pending.strength) || 0.025;
    uniforms.uSpeed.value = Number(pending.speed) || 2.2;
    uniforms.uFrequency.value = Number(pending.frequency) || 28;
    uniforms.uDecay.value = Number(pending.decay) || 7;
    uniforms.uIdle.value = pending.idle === false ? 0 : 1;
    uniforms.uIdleStrength.value = Number(pending.idleStrength) || 0.012;
  };

  let resizeFrame = 0;
  let lastWidth = 0;
  let lastHeight = 0;

  const applySize = (force = false) => {
    if (!renderer || !uniforms) return;
    const box = getRoot();
    const width = Math.max(Math.round(box.clientWidth), 1);
    const height = Math.max(Math.round(box.clientHeight), 1);
    if (!force && width === lastWidth && height === lastHeight) return;
    lastWidth = width;
    lastHeight = height;
    renderer.setSize(width, height, false);
    uniforms.uResolution.value.set(width, height);
    if (scene && camera) renderer.render(scene, camera);
  };

  const resize = () => {
    if (resizeFrame || !renderer) return;
    resizeFrame = requestAnimationFrame(() => {
      resizeFrame = 0;
      applySize();
    });
  };

  const updatePointer = (event) => {
    if (!uniforms) return;
    const rect = canvas.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    const isInside = event.clientX >= rect.left && event.clientX <= rect.right && event.clientY >= rect.top && event.clientY <= rect.bottom;
    if (!isInside) {
      targetActivity = 0;
      return;
    }
    uniforms.uTarget.value.set(
      (event.clientX - rect.left) / rect.width,
      1 - (event.clientY - rect.top) / rect.height
    );
    targetActivity = reducedMotion.matches ? 0 : 1;
  };

  const setTexture = (image) => {
    if (!image || !image.naturalWidth || !uniforms) return;
    const next = new THREE.Texture(image);
    next.colorSpace = THREE.NoColorSpace;
    next.minFilter = THREE.LinearFilter;
    next.magFilter = THREE.LinearFilter;
    next.needsUpdate = true;
    const prev = texture;
    texture = next;
    uniforms.uTexture.value = next;
    uniforms.uImageSize.value.set(image.naturalWidth, image.naturalHeight);
    if (prev) prev.dispose();
    if (renderer && scene && camera) renderer.render(scene, camera);
  };

  const syncTexture = (src) => {
    if (!src || src === lastLoadedSrc) return;
    const gen = ++loadGen;
    lastLoadedSrc = src;
    loadUrl(src).then((fresh) => {
      if (destroyed || gen !== loadGen) return;
      if (!fresh) {
        lastLoadedSrc = '';
        return;
      }
      if (uniforms) setTexture(fresh);
    });
  };

  const pollSource = () => {
    syncTexture(attrSrc(liveImage(canvas)));
  };

  const render = (now) => {
    if (destroyed) return;
    frame = requestAnimationFrame(render);
    pollSource();
    if (!visible || !renderer) return;
    const liveRoot = getRoot();
    if (liveRoot && !liveRoot.classList.contains('is-ready')) liveRoot.classList.add('is-ready');
    const delta = Math.min((now - last) / 1000, 0.05);
    last = now;
    uniforms.uTime.value += delta;
    uniforms.uPointer.value.lerp(uniforms.uTarget.value, 0.14);
    uniforms.uActivity.value += (targetActivity - uniforms.uActivity.value) * 0.08;
    renderer.render(scene, camera);
  };

  const waitForSrc = () => new Promise((resolve) => {
    const started = performance.now();
    const check = () => {
      const src = attrSrc(liveImage(canvas));
      if (src) {
        resolve(src);
        return;
      }
      if (destroyed || performance.now() - started > 10000) {
        resolve('');
        return;
      }
      requestAnimationFrame(check);
    };
    check();
  });

  const start = async () => {
    const src = await waitForSrc();
    if (destroyed || !el.isConnected || !src) return;
    const image = await loadUrl(src);
    if (destroyed || !image) return;
    lastLoadedSrc = src;

    renderer = new THREE.WebGLRenderer({
      canvas,
      alpha: false,
      antialias: false,
      powerPreference: 'high-performance'
    });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;

    scene = new THREE.Scene();
    camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
    geometry = new THREE.PlaneGeometry(2, 2);
    texture = new THREE.Texture(image);
    texture.colorSpace = THREE.NoColorSpace;
    texture.minFilter = THREE.LinearFilter;
    texture.magFilter = THREE.LinearFilter;
    texture.needsUpdate = true;

    uniforms = {
      uTexture: { value: texture },
      uTime: { value: 0 },
      uPointer: { value: new THREE.Vector2(0.5, 0.5) },
      uTarget: { value: new THREE.Vector2(0.5, 0.5) },
      uResolution: { value: new THREE.Vector2(1, 1) },
      uImageSize: { value: new THREE.Vector2(image.naturalWidth, image.naturalHeight) },
      uStrength: { value: 0.025 },
      uSpeed: { value: 2.2 },
      uFrequency: { value: 28 },
      uDecay: { value: 7 },
      uActivity: { value: 0 },
      uIdle: { value: 1 },
      uIdleStrength: { value: 0.012 }
    };
    applyProps(pending);

    material = new THREE.ShaderMaterial({
      uniforms,
      vertexShader: `
        varying vec2 vUv;
        void main() {
          vUv = uv;
          gl_Position = vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        precision highp float;
        uniform sampler2D uTexture;
        uniform float uTime;
        uniform vec2 uPointer;
        uniform vec2 uResolution;
        uniform vec2 uImageSize;
        uniform float uStrength;
        uniform float uSpeed;
        uniform float uFrequency;
        uniform float uDecay;
        uniform float uActivity;
        uniform float uIdle;
        uniform float uIdleStrength;
        varying vec2 vUv;

        vec2 coverUv(vec2 uv, vec2 screenSize, vec2 imageSize) {
          float screenRatio = screenSize.x / screenSize.y;
          float imageRatio = imageSize.x / imageSize.y;
          vec2 scale = vec2(1.0);
          if (screenRatio > imageRatio) {
            scale.y = imageRatio / screenRatio;
          } else {
            scale.x = screenRatio / imageRatio;
          }
          return (uv - 0.5) * scale + 0.5;
        }

        void main() {
          vec2 aspect = vec2(uResolution.x / max(uResolution.y, 1.0), 1.0);
          vec2 delta = (vUv - uPointer) * aspect;
          float distanceToPointer = length(delta);
          float wave = sin(distanceToPointer * uFrequency - uTime * uSpeed);
          float falloff = exp(-distanceToPointer * uDecay);
          float idleTime = uTime * 0.9;
          vec2 idleWave = vec2(
            sin(vUv.y * 12.0 + idleTime) + 0.5 * sin(vUv.y * 23.0 - idleTime * 1.3),
            cos(vUv.x * 14.0 - idleTime * 0.8) + 0.5 * sin(vUv.x * 21.0 + idleTime * 1.1)
          ) * uIdleStrength * uIdle * (1.0 - uActivity * 0.6);
          vec2 direction = normalize(delta + vec2(0.0001));
          vec2 displacement = direction * wave * falloff * uStrength * uActivity;
          displacement += idleWave;
          vec2 uv = coverUv(vUv + displacement, uResolution, uImageSize);
          gl_FragColor = texture2D(uTexture, clamp(uv, 0.001, 0.999));
        }
      `
    });

    scene.add(new THREE.Mesh(geometry, material));
    resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(getRoot());
    window.addEventListener('pointermove', updatePointer, { passive: true });
    window.addEventListener('pointerdown', updatePointer, { passive: true });
    applySize();
    getRoot().classList.add('is-ready');
    lastLoadedSrc = '';
    pollSource();
    frame = requestAnimationFrame(render);
  };

  start();

  return {
    update(next) {
      const prev = pending;
      applyProps(next);
      const imageChanged = !prev ||
        prev.image !== pending.image ||
        prev.width !== pending.width ||
        prev.height !== pending.height;
      if (imageChanged) lastLoadedSrc = '';
      pollSource();
    },
    setVisible(isVisible) {
      visible = isVisible;
    },
    dispose() {
      if (destroyed) return;
      destroyed = true;
      cancelAnimationFrame(frame);
      cancelAnimationFrame(resizeFrame);
      if (resizeObserver) resizeObserver.disconnect();
      window.removeEventListener('pointermove', updatePointer);
      window.removeEventListener('pointerdown', updatePointer);
      if (texture) texture.dispose();
      if (material) material.dispose();
      if (geometry) geometry.dispose();
      if (renderer) {
        renderer.dispose();
        renderer.forceContextLoss();
      }
      const root = getRoot();
      if (root) root.classList.remove('is-ready');
      canvas.remove();
    }
  };
}
