const transformHook = (rw) => {
  const clamp = (value, min, max, fallback) => {
    const number = Number(value);
    return Number.isFinite(number) ? Math.min(Math.max(number, min), max) : fallback;
  };

  const id = rw.node.id;
  const strength = clamp(rw.props.rippleStrength, 2, 80, 25);
  const speed = clamp(rw.props.rippleSpeed, 1, 8, 2);
  const frequency = clamp(rw.props.rippleFrequency, 6, 70, 28);
  const decay = clamp(rw.props.rippleDecay, 2, 18, 7);
  const idleStrength = clamp(rw.props.idleStrength, 1, 50, 12);
  const idle = rw.props.idleMotion !== false;
  const rippleImage = rw.props.rippleImage || {};

  rw.setRootElement({
    as: 'div',
    class: `component-${id} three-ripple`,
    args: {
      'data-three-ripple': '',
      'data-edit': rw.project.mode === 'edit' ? 'true' : 'false',
      'data-strength': String(clamp(rw.props.rippleStrength, 2, 80, 25) / 1000),
      'data-speed': String(clamp(rw.props.rippleSpeed, 1, 8, 2)),
      'data-frequency': String(clamp(rw.props.rippleFrequency, 6, 70, 28)),
      'data-decay': String(clamp(rw.props.rippleDecay, 2, 18, 7)),
      'data-idle': rw.props.idleMotion === false ? 'false' : 'true',
      'data-idle-strength': String(clamp(rw.props.idleStrength, 1, 50, 12) / 1000)
    }
  });

  rw.setProps({
    edit: rw.project.mode === 'edit',
    livePreviewProps: encodeURIComponent(JSON.stringify({
      image: rippleImage.image || '',
      width: rippleImage.width || 0,
      height: rippleImage.height || 0,
      strength: strength / 1000,
      speed: speed,
      frequency: frequency,
      decay: decay,
      idle: idle,
      idleStrength: idleStrength / 1000
    })),
    rippleStrength: clamp(rw.props.rippleStrength, 2, 80, 25),
    rippleSpeed: clamp(rw.props.rippleSpeed, 1, 8, 2),
    rippleFrequency: clamp(rw.props.rippleFrequency, 6, 70, 28),
    rippleDecay: clamp(rw.props.rippleDecay, 2, 18, 7),
    idleStrength: clamp(rw.props.idleStrength, 1, 50, 12)
  });
};

exports.transformHook = transformHook;

